    constructor(C _c) {
        c = _c;
    }

    function run(uint depositAmount, uint collectAmount) public payable {
        require(address(this).balance >= depositAmount);

        // Setup: deposit so the caller has a recorded balance and c holds Ether.
        c.Deposit{value: depositAmount}();

        // Read before-values through the public getter and address balance.
        uint beforeBalance = c.balances(address(this));
        uint beforeContractEth = address(c).balance;
        uint minSum = c.MinSum();

        // Deciding call: try to collect.
        // The contract must be able to honor collectAmount if it succeeds.
