    constructor(C _c) {
        c = _c;
    }

    function run(uint dep, uint am) public payable {
        require(address(this).balance >= dep);
        uint min = c.MinSum();
        c.SetMinSum(am);       // Ensure the caller's balance threshold is exactly am
        c.Initialized();      // Lock MinSum so Collect uses this threshold

        c.Deposit{value: dep}();
        uint beforeBal = c.balances(address(this));
        uint beforeEth = address(c).balance;

        bool reverted;
        try c.Collect(am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(c.balances(address(this)) == beforeBal - am);
            assert(address(c).balance == beforeEth - am);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint setMinSum, uint depositAmount, uint collectAmount) public payable {
        require(address(this).balance >= depositAmount);

        c.SetMinSum(setMinSum);
        c.SetLogFile(address(new LogFile()));
        c.Initialized();

        c.Deposit{value: depositAmount}();

        uint256 balBefore = c.balances(address(this));
        uint256 cEthBefore = address(c).balance;

        bool ok;
        try c.Collect(collectAmount) { ok = true; } catch { ok = false; }

        uint256 balAfter = c.balances(address(this));
        uint256 cEthAfter = address(c).balance;

        assert(!ok || (balBefore - balAfter == collectAmount && cEthBefore - cEthAfter == collectAmount));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint setMinSum, uint depositAmount, uint collectAmount) public payable {
        require(address(this).balance >= depositAmount);

        c.SetMinSum(setMinSum);
        c.SetLogFile(address(this));
        c.Initialized();

        c.Deposit{value: depositAmount}();

        uint256 balBefore = c.balances(address(this));
        uint256 cEthBefore = address(c).balance;

        bool ok;
        try c.Collect(collectAmount) { ok = true; } catch { ok = false; }

        uint256 balAfter = c.balances(address(this));
        uint256 cEthAfter = address(c).balance;

        assert(!ok || (collectAmount <= balBefore && cEthBefore - cEthAfter == collectAmount));
    }

    receive() external payable {}
}
